INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86933, 'spa', 'propósito negativo', 'Construcción dominante de propósito negativo, típicamente לְבִלְתִּי más infinitivo, que expresa «para que no, a fin de no, para no». Se encuentra 84 veces desde Génesis hasta Ezequiel, y gobierna advertencias divinas (Gn 3:11), medidas protectoras (Gn 4:15; Lv 18:30) y prohibiciones proféticas. Es el recurso preferido del escritor hebreo para las cláusulas finales negativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86935, 'spa', 'excepción o exclusión', 'Tras una negación precedente, בִּלְתִּי funciona como partícula exceptiva que significa «excepto, a menos que, sino solo». Pasajes clave incluyen Gn 21:26 («nadie me lo dijo excepto tú»), Gn 43:3-5 (los hermanos de José no pueden regresar «a menos que» Benjamín esté con ellos) y Éx 22:20 («el que sacrifique a cualquier dios excepto al Señor»). Estas 13 ocurrencias muestran a בִּלְתִּי trazando excepciones precisas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86939, 'spa', 'sin, ausencia', 'Indica privación o ausencia total —«sin, ninguno, no más»— describiendo un estado donde algo falta por completo. Las narrativas de la conquista de Josué lo emplean de modo impactante: Jos 8:22; 10:33; 11:8 describen enemigos «sin» sobreviviente alguno. Las 10 ocurrencias transmiten un estado absoluto de carencia más que una prevención intencionada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86940, 'spa', 'negación adverbial simple', 'Tres ocurrencias donde בִּלְתִּי funciona como negación adverbial simple «no», modificando un adjetivo o estado en vez de formar una cláusula de propósito. En 1 S 20:26, David «no está limpio» (בִּלְתִּי טָהוֹר). Nm 21:35 y Dt 3:3 lo usan de forma similar. Isaías 14:6 también lo emplea adverbialmente: «un golpe sin cesar», es decir, incesante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86950, 'spa', 'negación causal', 'Construcción de negación causal con la preposición מִן, que produce «porque no, por incapacidad de». Se encuentra en Nm 14:16, donde las naciones dirían que Dios mató a Israel en el desierto «por no poder» (מִבִּלְתִּי) llevarlos a la tierra prometida, y en Ez 16:28, describiendo insaciabilidad. Este matiz causal-privativo combina razón y negación en una sola construcción compacta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86964, 'spa', 'santuario, lugar alto cúltico', 'Sitio de culto elevado al aire libre, típicamente asociado con rituales ilícitos o de influencia cananea. Condenado a lo largo de Reyes y los profetas (1 R 12:31; 2 R 23:5), estos santuarios aparecen en todos los idiomas como sitios cúlticos elevados: español «lugares altos», francés «hauts lieux», alemán «Höhen». Las 92 ocurrencias abarcan fórmulas de condena, relatos de reforma y advertencias proféticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (86971, 'spa', 'altura, terreno elevado', 'Elevación topográfica, cresta o altura montañosa, usada en poesía y profecía. Dios «camina sobre las alturas de la tierra» (Am 4:13; Mi 1:3), y los fieles son puestos sobre lugares altos (Dt 32:13; 2 S 22:34). Las glosas multilingües muestran un marco geográfico más que cúltico: «alturas de» en vez de «lugares altos» como santuarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87004, 'spa', 'En, con (prep', 'En, con (prep. poética) — Preposición poética arcaica que funciona como forma expandida de beth, transmitiendo significados locativos (''en''), instrumentales (''con'') o direccionales (''hacia/a través de''). Restringida al verso elevado: Job la usa para lavarse ''con aguas de nieve'' (9:30) y fortalecer ''con la boca'' (16:4-5); Isaías para Moab pisoteado ''en su lugar'' (25:10); Deuteronomio 33:2 para el fuego ''desde'' la diestra de Dios. La enclítica -mo es un arcaísmo semítico noroccidental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87010, 'spa', 'Ciudad moabita', 'Asentamiento moabita que significa ''lugares altos'', situado en el itinerario de Israel por el desierto (Nm 21:19-20) y luego asignado a Rubén (Jos 13:17). La forma ampliada Bamot-Baal (Nm 22:41) revela su función como sitio cúltico cananeo: Balac llevó allí a Balaam para observar a Israel desde un punto sagrado dedicado a בַּעַל.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87011, 'spa', 'Hijo en constructo', 'Hijo o hijos en forma constructa, indicando parentesco o afiliación grupal. Este subconjunto de ocurrencias emplea la forma preposicional לְבֵן o formas sufijadas para expresar pertenencia, ya sea a un padre literal (2 R 19:37, donde Senaquerib es abatido por ''sus hijos'') o a una clasificación social (Jue 20:13, ''hijos de Belial'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87013, 'spa', 'hijo, descendiente varón', 'Descendencia masculina directa en sentido biológico o legal, con énfasis en la línea genealógica. Este sentido nuclear domina las genealogías, las narrativas de nacimiento y las promesas patriarcales. Las traducciones convergen uniformemente: español hijo, árabe اِبْن, hindi बेटा/पुत्र, confirmando la univocidad del parentesco directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87058, 'spa', 'hijos, pueblo (colectivo)', 'Uso colectivo donde בֵּן/בְּנֵי designa a un pueblo, comunidad o grupo humano en sentido amplio. ''Hijos de Israel'' equivale a ''los israelitas'', ''hijos de los hombres'' a ''la humanidad''. En este uso el término trasciende el parentesco individual para abarcar identidades nacionales, étnicas o comunitarias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87089, 'spa', 'cría de animales', 'Aplicación del término a las crías de animales: ''hijo de ganado'' es un becerro, ''hijo de paloma'' es un pichón. La metáfora de parentesco se extiende al reino animal, especialmente en contextos de sacrificio y legislación ritual. Español traduce cría, cachorro o pollo según la especie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87106, 'spa', 'Hijo (arameo) — Palabra aramea para ''hijo'', que funciona de manera idéntica al h', 'Hijo (arameo) — Palabra aramea para ''hijo'', que funciona de manera idéntica al hebreo בֵּן en cadenas patronímicas y expresiones relacionales más amplias. Se usa en fórmulas genealógicas a lo largo de Esdras (5:1-2; 6:14) y para ''los hijos de Israel'' colectivamente (Esd 6:16). En Daniel aparece en la visión trascendental de ''uno como un hijo de hombre'' (כְּבַר אֱנָשׁ, Dn 7:13), figura que recibe dominio universal del Anciano de Días.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87110, 'spa', 'Sentido activo del Pe''al (y participio pasivo)', 'Sentido activo del Pe''al (y participio pasivo): construir, edificar o erigir una estructura, referido tanto al templo de Jerusalén como a la ciudad de Babilonia. Las quince apariciones se concentran en la narración de Esdras sobre los exiliados que regresan y ''están construyendo'' la casa de Dios (Esd 5:2, 3, 4, 9, 11), con el decreto de Darío para que lo ''edifiquen'' (Esd 6:7, 8, 14). El orgullo de Nabucodonosor en Dn 4:27 completa el cuadro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87111, 'spa', 'Sentido reflexivo-pasivo del Hitpael', 'Sentido reflexivo-pasivo del Hitpael: ser construido o estar en proceso de construcción. Siete apariciones capturan la cuestión políticamente delicada de la reconstrucción durante el período persa. Los adversarios de Judá advierten que si Jerusalén ''es edificada'' de nuevo (Esd 4:13, 16), se rebelará, lo que llevó al decreto de que ''no sea construida'' (Esd 4:21). El decreto original de Ciro ordenó que el templo ''sea edificado'' (Esd 5:15; 6:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87125, 'spa', 'edificar, construir (Qal)', 'Sentido Qal activo central: edificar, construir o erigir físicamente una estructura —ciudad, casa, altar, muro, torre o fortificación. Con 316 ocurrencias domina el perfil del lema, abarcando toda la narrativa bíblica desde el primer altar (Gn 8:20) hasta la reconstrucción postexílica de las murallas de Jerusalén (Neh 2-6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87138, 'spa', 'ser edificado (Nifal)', 'Sentido pasivo y reflexivo Nifal: ser edificado, ser construido, ser establecido. Con 30 apariciones, funciona como pasivo natural del sentido 1: ciudades que «son edificadas» (Nm 21:27; Dt 13:16), el templo que «estaba siendo construido» (1 R 6:7). Pero emerge una extensión metafórica notable en las narrativas matriarcales: Raquel y Lea esperan «ser edificadas» mediante hijos (Gn 16:2; 30:3), explotando el juego de palabras entre בָּנָה y בֵּן.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87142, 'spa', 'constructor (participio Qal)', 'Participio activo Qal sustantivado que funciona como nombre de agente: «constructor(es)», «el que edifica». Con 27 ocurrencias, designa a trabajadores profesionales de construcción (1 R 5:18, los constructores de Salomón junto a los de Hiram) o a Dios como constructor maestro. El célebre Salmo 118:22 —«la piedra que desecharon los constructores»— se convirtió en texto cristológico capital.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87205, 'spa', 'edificado (participio pasivo Qal)', 'Participio pasivo Qal usado adjetivalmente: «edificado, construido», describiendo una estructura terminada más que el proceso de edificación. Solo 4 ocurrencias claras, pero cada una es distintiva: Jerusalén «como ciudad compactamente edificada» (Sal 122:3) y el cuello de la amada «como torre edificada» (Cnt 4:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87267, 'spa', 'Nombre dinástico de los reyes arameos de Damasco, que significa ''hijo del dios d', 'Nombre dinástico de los reyes arameos de Damasco, que significa ''hijo del dios de la tormenta Hadad.'' Al menos tres reyes llevaron este nombre: Ben-Hadad I, aliado de Asa contra Baasa (1 R 15:18-20); Ben-Hadad II, que guerreó contra Acab y fue confrontado por Eliseo (1 R 20:1-34; 2 R 6:24; 8:7-9); y Ben-Hadad III, hijo de Hazael (2 R 13:3, 24-25). Los registros asirios identifican a Ben-Hadad II como Adad-idri. Amós 1:4 profetiza fuego sobre sus palacios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87269, 'spa', 'Binui (nombre personal)', 'Nombre propio Binui (בִּנּוּי), que designa a varios israelitas postexílicos. Un jefe de familia que retornó con Zorobabel (Neh 7:15, paralelo a Bani en Esd 2:10), un levita que pesó los utensilios del templo (Esd 8:33) y selló el pacto (Neh 10:10), y hombres que repudiaron esposas extranjeras (Esd 10:30, 38). Las versiones en español, francés y alemán preservan la transliteración con variaciones mínimas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87276, 'spa', 'Bani', 'Nombre propio hebreo (בָּנִי, ''edificado'') llevado por múltiples individuos: (1) uno de los guerreros de David, ''el gadita'' (2 S 23:36; cf. 1 Cr 11:38); (2) levitas activos en el culto postexílico, la lectura de la Torá y la firma del pacto (1 Cr 6:46; Neh 3:17; 8:7; 9:4–5; 10:14); y (3) jefes de familias de la época del retorno (Esd 2:10; 10:29, 34). El francés ''fils-de'' en algunos contextos refleja confusión con el patronímico בֵּן.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87279, 'spa', 'Nombre levítico postexílico', 'Nombre propio principalmente levítico del período postexílico. Un Buni estuvo en la plataforma durante la ceremonia del pacto (Nehemías 9:4), otro firmó el pacto (Nehemías 10:15) y otro aparece en una genealogía levítica (Nehemías 11:15). Las incertidumbres textuales sugieren posible confusión con nombres similares (Bani, Binúi), pero el nombre está bien atestiguado en el entorno de la restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87282, 'spa', 'El nombre propio Benayahu/Benayah (''Yah ha edificado''), llevado por al menos och', 'El nombre propio Benayahu/Benayah (''Yah ha edificado''), llevado por al menos ocho individuos. El más notable es el hijo de Joiada, que comandaba a los cereteos y peleteos de David (2 S 8:18; 20:23) y aseguró la sucesión de Salomón (1 R 1-2). Las 42 apariciones, tanto en la grafía -yahu como en la -yah, designan un solo nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87290, 'spa', 'Benjamín (nombre propio)', 'El nombre propio Benjamín, referido al hijo menor de Jacob nacido de Raquel, y por metonimia a la tribu israelita y su territorio asignado. A lo largo de 169 apariciones, el nombre figura en la narrativa patriarcal (Gn 42:4), las listas censales tribales (Nm 1:36), las descripciones territoriales (Jos 18:20) y los oráculos proféticos (Os 5:8). Las traducciones lo transliteran de manera uniforme: ''Benjamín'' en español, ''Benjamin'' en francés y alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87310, 'spa', 'Benjaminita (gentilicio) — Designación tribal que identifica a un miembro de la ', 'Benjaminita (gentilicio) — Designación tribal que identifica a un miembro de la tribu de Benjamín (''hijo de la mano derecha''). Aplicado a Ehúd, el juez zurdo y libertador de la opresión moabita (Jue 3:15), al anciano de Gabaa que hospedó al levita (Jue 19:16), a Saúl que humildemente señala la pequeñez de Benjamín (1 Sam 9:21; 22:7) y a Simei ben Gera que maldijo a David durante la rebelión de Absalón (2 Sam 16:11; 19:16; 1 Re 2:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87318, 'spa', 'Edificio, estructura', 'Edificación o estructura arquitectónica construida, empleada en la visión del templo de Ezequiel para describir el muro envolvente (Ez 40:5), la edificación posterior (Ez 41:12, 15) y otras partes del complejo sagrado (Ez 42:1, 5, 10). La evidencia multilingüe lo traduce consistentemente con términos de construcción — español ''edificio'', francés ''bâtiment'', alemán ''Gebäude'' — confirmando un sentido arquitectónico concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87329, 'spa', 'Uvas agrias', 'Uvas verdes o agrias, fruto que no ha alcanzado la madurez y tiene un sabor desagradable. En Isaías 18:5 aparece en una metáfora agrícola sobre la poda divina de las naciones. Job 15:33 compara al impío con una vid que deja caer sus בֹּסֶר. El uso proverbial en Jeremías 31:29-30 y Ezequiel 18:2 presenta la imagen de las uvas agrias como símbolo de culpa heredada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87330, 'spa', 'Buscar, pedir — Pedir, solicitar o suplicar a alguien, ya sea una autoridad huma', 'Buscar, pedir — Pedir, solicitar o suplicar a alguien, ya sea una autoridad humana o Dios. Este sentido Qal abarca a Daniel pidiendo audiencia al rey (Dn 2:16), orando a Dios por revelación (Dn 2:18, 23) y el decreto que prohíbe peticiones a cualquier dios u hombre excepto al rey (Dn 6:8, 13). Daniel 6:12 y 6:14 describen a Daniel ''haciendo petición'' ante Dios en desafío al edicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87336, 'spa', 'Buscar con diligencia (intensivo Piel) — Buscar con intensidad o determinación a', 'Buscar con diligencia (intensivo Piel) — Buscar con intensidad o determinación acentuadas, expresadas mediante la conjugación Piel. La única aparición en Daniel 4:36 describe a los consejeros y nobles de Nabucodonosor que lo ''buscaron'' diligentemente tras su restauración de la locura. La intensificación del Piel sugiere una búsqueda activa, quizá ansiosa, no un mero preguntar sino un rastrear.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87340, 'spa', 'en favor de, por', 'El sentido benefactivo dominante, que aparece en aproximadamente la mitad de las ocurrencias. El árabe lo traduce con preposiciones de propósito (مِنْ أَجْلِ, لِأَجْلِ), el coreano con 위하여 y el suajili con kwa ajili ya, confirmando la lectura ''en beneficio de''. Típico en contextos sacerdotales donde se hace expiación ''por'' alguien (Lv 9:7; 16:6). Los sufijos pronominales (בַּעֲדִי, בַּעֲדוֹ) se adjuntan directamente para indicar al beneficiario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87341, 'spa', 'a través de, por', 'Paso espacial a través de una abertura o hueco, como cuando Rajab descuelga a los espías por la ventana (Jos 2:15) o la madre de Sísara mira a través de la celosía (Jue 5:28). El árabe مِنْ خِلَالِ y el coreano 통하여 apuntan a ''a través'' en lugar de ''detrás'', distinguiendo este sentido del posicional. La noción subyacente de separación —moverse de un lado para emerger en el otro— es el nexo etimológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87345, 'spa', 'detrás de, tras', 'Sentido posicional de ''detrás'', indicando ubicación o movimiento en la parte posterior de algo. Dios cierra la puerta detrás de Noé (Gn 7:16); la grasa se cierra detrás de la hoja (Jue 3:22). El árabe وَرَاءَ y el alemán hinter traducen consistentemente este sentido espacial. La preposición aquí marca lo que está al otro lado de una barrera, preservando la idea radical de separación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87353, 'spa', 'en intercambio por', 'Dos ocurrencias en Job 2:4, donde Satanás dice ''piel por piel'' — una fórmula proverbial de intercambio. El matiz preciso es debatido; las traducciones multilingües se dividen entre ''por'' (intercambio) y ''a causa de''. El contexto sugiere un ''a cambio de'' transaccional, lo que lo convierte en un uso especializado distinto de la simple benefacción o la causación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87355, 'spa', 'alrededor de, en torno', 'Sentido de rodear o cercar, especialmente en relación con la protección divina. Job 1:10 es el pasaje paradigmático: Dios lo ha ''cercado alrededor'' por todos lados. El árabe حَوْلَ y el suajili kuzunguka confirman ''alrededor'' en vez de ''detrás''. También en Sal 3:3, donde Dios es escudo ''en torno'' al salmista. La lectura de cerco se extiende naturalmente de la interposición al envolvimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87371, 'spa', 'temporal: dentro de, después de', 'Uso temporal-adverbial raro, atestiguado en 1 S 4:18 (Elí había juzgado a Israel cuarenta años) e Is 7:8 (dentro de sesenta y cinco años). El árabe وَ فِي بَعدِ y el suajili na-ndani-ya respaldan la lectura como ''dentro de'' o ''después de'' un período de tiempo — extensión del espacial ''dentro de un límite'' al dominio temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87373, 'spa', 'a causa de, por motivo de', 'Sentido causal —''a causa de, por motivo de''— que aparece en Gn 20:18 (Yahvé cerró matrices a causa de Sara), 1 S 1:6 y Pr 6:26. El árabe بِسَبَبِ y el suajili kwa sababu ya lo marcan como genuinamente causal, distinto del benefactivo. El desarrollo semántico de ''en favor de'' a ''a causa de'' sigue un camino frecuente en las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87387, 'spa', 'Inquirir o hinchar', 'Buscar, inquirir o preguntar, especialmente ante un oraculo profetico. Usado en Isaias 21:12 donde el centinela invita a los consultantes edomitas a volver y preguntar de nuevo. El cognado arameo (בעא, ''buscar'') y el Nifal pasivo ''escudrinado'' en Abdias 1:6 refuerzan este significado central de investigacion deliberada. Incluye tambien el sentido fisico de hervir o abultarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87389, 'spa', 'Nombre personal que identifica a dos individuos', 'Nombre personal que identifica a dos individuos: (a) padre de Bela, un antiguo rey edomita que gobernó antes de la monarquía israelita (Gn 36:32; 1 Cr 1:43); y (b) padre del profeta-adivino Balaam, donde «hijo de Beor» funciona como un patronímico casi fijo (Nm 22:5; 24:3, 15; Dt 23:5; Jos 13:22; 24:9; Mi 6:5). Si se trata de la misma persona es objeto de debate; los contextos edomita y mesopotámico sugieren figuras distintas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87392, 'spa', 'Nombre propio Boaz (בֹּעַז), referido principalmente al acaudalado betlemita par', 'Nombre propio Boaz (בֹּעַז), referido principalmente al acaudalado betlemita pariente redentor que se casó con Rut la moabita (Rut 2-4), asegurando el linaje davídico y mesiánico. También designa el pilar izquierdo en la entrada del templo de Salomón (1 R 7:21; 2 Cr 3:17), donde la LXX de Crónicas lo traduce como ischus (''fuerza''), sugiriendo la posible etimología ''en él hay fuerza.'' Un descendiente menor de Caleb también lleva el nombre (1 Cr 2:11-12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87400, 'spa', 'Bestias, ganado', 'Animales domésticos o ganado vistos colectivamente, incluyendo bestias de carga y reses. En Génesis 45:17, José indica a sus hermanos que carguen sus בְּעִיר (asnos, cf. 44:3, 13). En el Código de la Alianza (Éx 22:4-5), el término aparece en una ley sobre daños por pastoreo. En Números 20:4, 8, 11 cubre el ganado de la congregación que necesita agua en Meribá, y en el Salmo 78:48 se usa en paralelo con los rebaños.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87406, 'spa', 'Ser señor de, dominar — Ejercer autoridad, dominio o posesión', 'Ser señor de, dominar — Ejercer autoridad, dominio o posesión. Este sentido aparece en contextos donde la metáfora matrimonial se desvanece y queda la autoridad pura: ''otros señores fuera de ti nos han dominado'' (Is 26:13), y los pasajes disputados en Jeremías donde Dios dice ''fui señor sobre ellos'' (Jer 3:14; 31:32). El sustantivo cognado בַּעַל (''señor, dueño'') subraya la conexión entre posesión y autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87410, 'spa', 'Casarse, ser esposo de — Entrar en o mantener una relación matrimonial', 'Casarse, ser esposo de — Entrar en o mantener una relación matrimonial. El Qal activo describe el acto de tomar esposa (Gn 20:3; Dt 21:13; 22:22; 24:1), mientras que el participio pasivo Qal בְּעוּלָה significa ''mujer casada'' (Is 54:1; 62:4). Isaías 62:5 usa el verbo dos veces en paralelo: ''como el joven se casa con la doncella, así tus hijos se casarán contigo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87422, 'spa', 'Señor o gobernante de una ciudad — el sentido cívico-político de señores, gobern', 'Señor o gobernante de una ciudad — el sentido cívico-político de señores, gobernantes o ciudadanos principales de una ciudad o región (27 ocurrencias), destacando los ''señores de Siquem'' cuya volátil alianza con Abimelec domina la narrativa de Jueces 9. También se aplica a los señores de Jericó (Jos 24:11), los arqueros que hostigaron a José (Gn 49:23, donde בַּעֲלֵי חִצִּים significa literalmente ''señores de flechas''), y los gobernantes de los lugares altos de Moab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87423, 'spa', 'Dueño o amo de propiedad — el sentido jurídico-económico principal de dueño o am', 'Dueño o amo de propiedad — el sentido jurídico-económico principal de dueño o amo de bienes (40 ocurrencias), que abarca la propiedad de animales (Éx 21:28-29, 34; 22:8-14), casas (Jue 19:22-23), campos (Job 31:39), pozos (Éx 21:34) y deudas (Dt 15:2). El Código de la Alianza en Éxodo 21-22 concentra un denso grupo de usos, estableciendo בַּעַל como el término legal por defecto para el propietario con la responsabilidad correspondiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87424, 'spa', 'Esposo — el sentido doméstico-relacional de esposo o señor marital (12 ocurrenci', 'Esposo — el sentido doméstico-relacional de esposo o señor marital (12 ocurrencias), donde בַּעַל designa al cónyuge de una mujer. Deuteronomio 22:22 y 24:4 lo emplean en legislación sobre divorcio y adulterio; 2 Samuel 11:26 lo aplica a Urías en la narrativa de Betsabé; y Oseas 2:16 explota magistralmente la doble resonancia del término con la deidad cananea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87441, 'spa', 'Poseedor de una cualidad — la construcción idiomática atributiva ''ba''al de X'' qu', 'Poseedor de una cualidad — la construcción idiomática atributiva ''ba''al de X'' que significa ''alguien caracterizado por o poseedor de una cualidad'' (2 ocurrencias en los datos, aunque el patrón es generalizado en hebreo). Proverbios 1:17 habla de un בַּעַל de alas (una criatura alada), e Isaías 41:15 describe un trillo nuevo como בַּעַל de dientes (con filos cortantes). El árabe ذو (poseedor de) funciona de manera idéntica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87453, 'spa', 'Aliado de pacto — una única ocurrencia en Génesis 14', 'Aliado de pacto — una única ocurrencia en Génesis 14:13 donde בַּעֲלֵי בְרִית designa a los ''aliados de pacto'' o ''socios de alianza'' de Abram: Mamre, Escol y Aner. La construcción בַּעֲלֵי בְרִית (literalmente ''señores/poseedores de un pacto'') representa un modismo diplomático-tratadístico donde בַּעַל se extiende de la propiedad a la obligación pactada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87458, 'spa', 'Oficial, jefe de guardia — una única ocurrencia en Jeremías 37', 'Oficial, jefe de guardia — una única ocurrencia en Jeremías 37:13 donde בַּעַל פְּקִדֻּת designa a un ''capitán de la guardia'' u ''oficial de inspección'', literalmente un ''señor de supervisión''. El término se aplica a Irías, quien arresta a Jeremías en la Puerta de Benjamín bajo sospecha de deserción. Este título especializado extiende בַּעַל al ámbito de la autoridad militar-administrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87463, 'spa', 'Baal (la deidad)', 'Baal (la deidad): el dios cananeo singular de la tormenta, cuyo culto rivalizaba con YHWH. Todas las traducciones lo tratan como nombre propio: el Baal, con el artículo definido señalando al dios específico. El desafío de Elías en el Carmelo (1 Re 18:21) y la destrucción del altar de Baal por Gedeón (Jue 6:25-32) son los pasajes definitorios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87466, 'spa', 'Los Baales (manifestaciones del culto)', 'Los Baales (manifestaciones del culto): el plural que designa las diversas manifestaciones locales, imágenes de culto o formas regionales de la adoración a Baal en Canaán. La fórmula deuteronomista «abandonaron al SEÑOR y sirvieron a los Baales» (Jue 2:11; 10:6) emplea este plural como acusación colectiva del culto sincrético a lo largo de la historia de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87477, 'spa', 'Nombre propio y topónimo', 'Sustantivo propio que designa una ciudad simeonita (1 Cr 4:33, equivalente a Baalat-Beer) o un nombre personal llevado por un rubenita (1 Cr 5:5) y un gabaonita (1 Cr 8:30; 9:36). A diferencia de la deidad בַּעַל adorada por los cananeos, este homógrafo funciona exclusivamente como identificador geográfico o genealógico, derivado del significado semítico común ''señor''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87478, 'spa', 'Título administrativo persa', 'Título de un funcionario administrativo persa: ''señor del decreto'' o ''comandante''. Rehum el ''comandante'' y Simsai el escriba escriben a Artajerjes oponiéndose a la reconstrucción de Jerusalén (Esdras 4:8, 9). La respuesta del rey emplea el mismo título (Esdras 4:17). Las traducciones lo vierten como ''oficial al mando'' o lo dejan transliterado, reconociéndolo como una designación oficial de rango.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87480, 'spa', 'Límite norte de conquista', 'El punto más septentrional de la conquista israelita, una ciudad en el valle del Líbano cerca del monte Hermón. Las campañas de Josué se extendieron ''desde Baal-gad en el valle del Líbano al pie del monte Hermón'' hasta el Néguev (Josué 11:17; 12:7; 13:5). El nombre sugiere un lugar de culto cananeo dedicado a Baal como dios de la fortuna (Gad), y servía como hito geográfico fijo del límite norte de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87481, 'spa', 'Dueña o señora', 'Mujer que posee, domina o se caracteriza por un ámbito o habilidad particular. La construcción בַּעֲלַת (''señora de'') se une a un sustantivo que define la relación: ''señora de la casa'' en 1 Reyes 17:17, ''señora de un espíritu nigromante'' en Endor (1 Sam 28:7) y ''señora de hechicerías'' describiendo el poder seductor de Nínive (Nah 3:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87482, 'spa', 'Toponimo en Juda', 'Nombre propio de lugar que designa una ciudad en Juda equiparada con Quiriat-Jearim y Quiriat-Baal (Jos 15:9-11; 1 Cr 13:6), desde la cual David traslado el arca. El nombre significa ''senora/duena'', senalando un sitio de culto cananeo pre-israelita. Una segunda localidad llamada Baala en Josue 15:29 se encuentra en el distrito meridional del Neguev.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87485, 'spa', 'Deidad filistea de Ecrón', 'La deidad filistea de Ecrón, ''señor de las moscas'' (בַּעַל זְבוּב), consultada por el herido rey Ocozías en 2 Reyes 1:2, 3, 6, 16. Todas las tradiciones de traducción conservan el nombre compuesto: español ''Baal-zebub''. La forma preposicional (לבעל זבוב, ''a Baal-zebub'') marca el acto de Ocozías de buscar un oráculo de un dios extranjero en lugar de consultar al Dios de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87486, 'spa', 'Nombre teoforico propio', 'Nombre propio teoforico que significa ''Baal es misericordioso'', llevado por (a) un rey de Edom en el linaje de Esau (Gn 36:38-39; 1 Cr 1:49-50), y (b) un oficial gederatita encargado de las plantaciones de olivos y sicomoros de David (1 Cr 27:28). El cognado fenicio Anibal invierte los mismos elementos, y el asirio Baalhanunu confirma la amplia difusion del nombre en las culturas semiticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87494, 'spa', 'Ciudad transjordana disputada', 'Ciudad en la meseta moabita reconstruida por Rubén (Números 32:38), habitada por rubenitas (1 Crónicas 5:8) y posteriormente devuelta al dominio moabita (Ezequiel 25:9). El nombre ''Baal de la morada'' apunta a un santuario local. Sus variantes incluyen Bet-baal-meón y Beón. La actual Ma''ín conserva el antiguo topónimo. El vaivén de su control refleja la frontera en disputa entre Israel y Moab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87495, 'spa', 'Baal Peor', 'La deidad moabita Baal según era adorada en el sitio de Peor y, por extensión, la infame apostasía cúltica asociada a ese lugar. Cada ocurrencia remite al desastre de Sitim en Números 25, ya sea narrando el evento (Num 25:3, 5), citándolo como advertencia (Deut 4:3), lamentándolo en la adoración (Sal 106:28) o invocándolo proféticamente (Os 9:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87500, 'spa', 'Topónimo conmemorativo', 'Nombre propio que designa el campo de batalla donde David venció a los filisteos, atestiguado en 2 Sam 5:20 y 1 Cr 14:11. El nombre funciona como un topónimo etiológico: David nombra el lugar para conmemorar la irrupción de Dios. Las traducciones al español conservan la transliteración del compuesto hebreo, añadiendo preposiciones direccionales según el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87501, 'spa', 'Lugar en Egipto', 'Sitio en Egipto junto al mar Rojo donde Israel acampó antes del cruce del éxodo. Moisés ordena al pueblo acampar frente a Baal-zefón (Éxodo 14:2), el ejército de Faraón los alcanza allí (Éxodo 14:9) y Números confirma la ubicación (Números 33:7). El nombre ''Baal del norte'' remite a un santuario cananeo en Egipto, que irónicamente se convierte en escenario del triunfo de Yahvé.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87503, 'spa', 'Ciudad en Dan', 'Ciudad incluida en la heredad de Dan (Josué 19:44) y fortificada posteriormente por Salomón (1 Reyes 9:18; 2 Crónicas 8:6). El nombre teofórico sugiere un santuario cananeo, posiblemente dedicado a una diosa (Baalat/señora). El programa constructivo de Salomón incluyó Baalat junto a Gezer y otras ciudades estratégicas, lo cual indica su valor en la red defensiva o administrativa del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87507, 'spa', 'Nombre propio israelita', 'Nombre compartido por funcionarios salomónicos y un jefe de familia postexílico. Baana hijo de Ahilud gobernaba el distrito del valle de Jezreel (1 Reyes 4:12); Baana hijo de Husai gobernaba en Aser (1 Reyes 4:16). Siglos después, un Baana (o su descendiente) reconstruyó parte de la muralla de Jerusalén (Nehemías 3:4). La recurrencia del nombre indica que estaba bien establecido en la onomástica israelita, aunque los individuos son distintos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87508, 'spa', 'Baaná (nombre propio)', 'Baaná — nombre propio que llevan al menos cuatro personas: (1) un capitán benjaminita que, con su hermano Recab, asesinó a Isboset y fue ejecutado por David (2 Sam 4:2-9); (2) el padre de Heleb/Heled, uno de los treinta valientes de David (2 Sam 23:29; 1 Cr 11:30); (3) un líder de los que regresaron del exilio (Esd 2:2; Neh 7:7); y (4) un jefe que selló el pacto en tiempos de Nehemías (Neh 10:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87510, 'spa', 'Purgar, eliminar el mal', 'Purgar, eliminar el mal: el sentido metafórico-legal distintivo de la fórmula deuteronómica וּבִעַרְתָּ הָרָע מִקִּרְבֶּךָ, «quitarás el mal de en medio de ti» (Dt 13:5; 17:7, 12; 19:13, 19; 21:21; 22:21-24; 24:7). Aquí la metáfora del fuego se ha trasladado completamente a la remoción moral y comunitaria. El español emplea quitar y barrer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87511, 'spa', 'Arder, estar en llamas', 'Arder, estar en llamas: combustión intransitiva — fuego que arde, se enciende o resplandece sin un agente explícito. Es el sentido base del Qal y Pual: la zarza que «ardía en fuego y no se consumía» (Éx 3:2), el fuego que «ardió entre ellos» en Tabera (Nm 11:1, 3), o el monte Sinaí «ardiendo en fuego» (Dt 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87515, 'spa', 'Encender, hacer arder (Hifil)', 'Encender, hacer arder (Hifil): quemar en sentido causativo en la forma Hifil — encender o hacer que algo arda, a menudo con una fuerza causativa más directa que el Piel. El incendiario que «encendió fuego en un campo» (Éx 22:6), Sansón prendiendo fuego al grano filisteo con zorras y antorchas (Jue 15:5), y el juicio de Dios declarado como «encenderé un fuego» (Ez 5:2; 2 Cr 28:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87517, 'spa', 'Encender, prender fuego (Piel)', 'Encender, prender fuego (Piel): quemar de forma causativa o intensiva en el Piel — encender, prender o provocar la combustión de algo, con un agente explícito. Se distingue del sentido 1 por la transitividad: alguien enciende fuego en sábado (Éx 35:3), el sacerdote mantiene el fuego del altar (Lv 6:12), o se mantienen encendidas las lámparas del templo (2 Cr 4:20; 13:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87569, 'spa', 'Ser embrutecido, ser necio', 'Ser embrutecido, necio o torpe de corazón, comportándose como una bestia irracional en lugar de como una persona capaz de discernimiento moral y espiritual. La literatura profética predomina: Isaías 19:11 se burla de los consejeros del faraón, el Salmo 94:8 reprende a los insensatos y Jeremías condena a quienes son incapaces de conocer a Dios (Jer 10:8, 14, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87573, 'spa', 'Apacentar, hacer pastar', 'Apacentar, dejar que el ganado paste o consumir vegetación por pastoreo. Las formas Piel e Hifil están atestiguadas en el Código de la Alianza (Éx 22:5). El Hifil yav''er significa «hacer que sea pastado» (enviar los animales propios al campo ajeno), mientras que el Piel uvi''er significa «alimentar, apacentar». Este uso agrícola concreto conserva la conexión etimológica con be''ir («ganado»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87578, 'spa', 'Brutalidad o insensatez', 'Brutalidad o insensatez estupida, empleada tanto como cualidad abstracta como designacion concreta de la persona que carece de percepcion espiritual. Emparejada con ''necio'' (כְּסִיל) en la poesia sapiencial (Sal 49:10; 92:6), transmite no mera ignorancia sino una obstinada torpeza ante los caminos de Dios. La autoacusacion del salmista en Salmo 73:22 y la confesion de Agur en Proverbios 30:2 muestran que puede expresar tambien humildad piadosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87581, 'spa', 'Nombre propio de Baasa hijo de Ahías, tercer rey del reino del norte de Israel, ', 'Nombre propio de Baasa hijo de Ahías, tercer rey del reino del norte de Israel, que reinó aproximadamente entre 909 y 886 a.C. Llegó al poder asesinando a Nadab y aniquilando la dinastía de Jeroboam (1 R 15:27-29), y luego fortificó Ramá contra Judá (1 R 15:17). A pesar de su energía política, el historiador deuteronomista lo condena por continuar en los pecados de Jeroboam (1 R 16:1-7). El profeta Jehú hijo de Hananí pronunció la sentencia contra su casa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87586, 'spa', 'Aterrorizar — Aterrorizar, espantar o sobresaltar a alguien — el sentido causati', 'Aterrorizar — Aterrorizar, espantar o sobresaltar a alguien — el sentido causativo Piel, donde un agente o fuerza inflige terror sobre otro. Este es el uso dominante, apareciendo a lo largo de Job y los Salmos: un espíritu malo ''aterrorizó'' a Saúl (1 S 16:14-15), torrentes de destrucción ''aterrorizaron'' a David (2 S 22:5; Sal 18:5), y Job repetidamente acusa a Dios de aterrorizarlo (Job 7:14; 9:34; 13:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87589, 'spa', 'Ser aterrorizado — Ser aterrorizado, consternado o vencido por el miedo — el Nif', 'Ser aterrorizado — Ser aterrorizado, consternado o vencido por el miedo — el Nifal pasivo, donde el sujeto experimenta el terror en vez de infligirlo. Las tres ocurrencias marcan momentos de encuentro dramático con un poder abrumador: David ''fue aterrorizado'' ante el ángel del SEÑOR en la era (1 Cr 21:30), Amán ''fue aterrorizado'' ante el rey y la reina cuando su complot fue expuesto (Est 7:6), y Daniel cayó postrado en terror ante la visión angélica (Dan 8:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87601, 'spa', 'Terreno pantanoso', 'Suelo cenagoso y anegado, hábitat natural de plantas palustres. En Job 8:11 el término se empareja con ''agua'' como condición necesaria para el crecimiento de los juncos. En Ez 47:11 la forma plural describe ciénagas estancadas que quedan excluidas del río purificador, contrastando el estancamiento con la renovación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87603, 'spa', 'Clan postexílico', 'Nombre de familia o clan entre los exiliados que regresaron a Judá. Esdras registra 323 ''hijos de Bezai'' (Esdras 2:17), Nehemías anota 324 (Nehemías 7:23) y un líder llamado Bezai selló el pacto (Nehemías 10:18). La familia evidentemente mantuvo su identidad durante el exilio y contribuyó al liderazgo y al compromiso de la comunidad restaurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87604, 'spa', 'Vendimia, cosecha de uvas', 'La vendimia o cosecha de uvas, la actividad estacional de recoger uvas maduras del viñedo. Denota literalmente la temporada de cosecha en Levítico 26:5 (la trilla que alcanza la vendimia como señal de bendición) e Isaías 32:10 (la vendimia que falla como juicio). Se usa figuradamente en Isaías 24:13 y Miqueas 7:1, donde el rebusco tras la vendimia simboliza escasez y desolación. Jeremías 48:32 lamenta la destrucción de la vendimia de Moab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87611, 'spa', 'Betsalel (nombre propio)', 'Betsalel — nombre propio teofórico (בְּצַלְאֵל, ''a la sombra/protección de El'') que designa principalmente al maestro artesano del Tabernáculo, de la tribu de Judá. Dios lo llenó de su Espíritu en sabiduría, inteligencia y destreza (Éx 31:2-5; 35:30-35) para ejecutar la elaborada construcción de los enseres del Tabernáculo, incluida el Arca del Pacto (Éx 37:1). Aparece también en las genealogías de Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87615, 'spa', 'Codiciar ganancia, ser avaro — El sentido moral-adquisitivo', 'Codiciar ganancia, ser avaro — El sentido moral-adquisitivo: ser codicioso de ganancia, ambicionar provecho deshonesto. La forma participial botse''a funciona casi como un término técnico para el que lucra injustamente. Proverbios advierte que el codicioso de ganancia perturba su propia casa (Pr 15:27), y Jeremías acusa a profeta y sacerdote por igual: ''todos codician ganancia'' (Jer 6:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87618, 'spa', 'Cortar, cercenar — El sentido físico concreto', 'Cortar, cercenar — El sentido físico concreto: cortar, cercenar o separar. El Ezequías de Isaías lamenta que Dios lo corta como un tejedor que corta el hilo del telar (Is 38:12), y el salmista ora para que los enemigos sean ''cortados'' (Sal 76:12). En Joel 2:8 el ejército de langostas no se desvía de su curso. Este es el núcleo etimológico del cual surgen los otros sentidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87623, 'spa', 'Terminar, completar, cumplir — El sentido completivo', 'Terminar, completar, cumplir — El sentido completivo: terminar, llevar a cabo, cumplir. Cuando Zacarías profetiza que las manos de Zorobabel terminarán el Templo (Zac 4:9), y cuando Lamentaciones declara que el SEÑOR ha cumplido su palabra de juicio (Lm 2:17), batsa'' ha pasado de ''cortar'' a ''abrirse paso hasta la conclusión''. Isaías 10:12 lo usa para Dios terminando su obra en el monte Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87630, 'spa', 'Provecho, ganancia o ventaja en un sentido neutro o interrogativo', 'Provecho, ganancia o ventaja en un sentido neutro o interrogativo: ''¿qué provecho hay?'' Este sentido (7 apariciones) despoja al término de todo juicio moral, dejando una pregunta económica o existencial directa. Judá pregunta ''¿qué ganancia hay si matamos a nuestro hermano?'' (Gn 37:26), Job demanda ''¿qué provecho para el Todopoderoso si eres justo?'' (Job 22:3), y el salmista interroga ''¿qué provecho hay en mi sangre?'' (Sal 30:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87631, 'spa', 'Ganancia injusta, lucro deshonesto, codicia — ganancia obtenida mediante explota', 'Ganancia injusta, lucro deshonesto, codicia — ganancia obtenida mediante explotación, soborno o violencia. Es el sentido dominante (15 apariciones), presente tanto en la denuncia profética como en la instrucción sapiencial. Éxodo 18:21 exige líderes que aborrezcan בֶּצַע; Proverbios 1:19 advierte que la ganancia codiciosa ''quita la vida a sus poseedores.'' Los profetas condenan a quienes persiguen lucro deshonesto (Jer 6:13; Ez 22:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87643, 'spa', 'Botín o despojos tomados en batalla — ganancia material concreta obtenida median', 'Botín o despojos tomados en batalla — ganancia material concreta obtenida mediante la guerra. Este sentido aparece una sola vez en el Cántico de Débora (Jue 5:19), donde los reyes de Canaán pelearon en Taanac pero ''no tomaron botín de plata.'' Se distingue claramente de los sentidos abstractos morales y económicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87647, 'spa', 'Masa para hornear', 'Masa, con o sin levadura, en la fase de amasado antes del horneado. La masa sin fermentar sacada de Egipto (Éx 12:34, 39) se convirtió en símbolo de premura y liberación divina. Fuera del Éxodo, Tamar amasa para Amnón (2 Sam 13:8), mujeres preparan tortas para la Reina del Cielo (Jer 7:18) y Oseas la emplea metafóricamente (Os 7:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87649, 'spa', 'El uso participial-adjetival que describe ciudades, murallas y fortalezas como f', 'El uso participial-adjetival que describe ciudades, murallas y fortalezas como fortificadas e inaccesibles. El aterrorizado informe de los espías en Números 13:28 y Deuteronomio 1:28 — ciudades ''grandes y fortificadas hasta el cielo'' — es paradigmático. Veinticinco apariciones se concentran en Deuteronomio y las narrativas de la conquista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87655, 'spa', 'Los tallos verbales derivados', 'Los tallos verbales derivados: Nifal ''ser impedido, ser imposible'' y Piel ''fortificar, reforzar defensas''. Génesis 11:6 declara que nada será ''impedido'' a la humanidad unida; Job 42:2 confiesa que ningún propósito de Dios puede ser frustrado. Isaías 22:10 emplea el Piel para fortalecer activamente una muralla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87657, 'spa', 'El Qal agrícola', 'El Qal agrícola: recoger o cosechar uvas de la vid. Levítico 25:5, 11 prohíben la vendimia durante los años sabáticos y de jubileo; Jueces 9:27 registra la cosecha de uvas de Siquem; Jeremías 6:9 y 49:9 utilizan ''vendimiador'' como figura retórica. El vocablo conecta con el amplio vocabulario bíblico de viña y cosecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87671, 'spa', 'Nombre propio (lugar/persona)', 'Nombre propio que significa ''fortaleza'', aplicado a (a) una ciudad levítica de refugio en territorio de Rubén al este del Jordán (Dt 4:43; Jos 20:8; 21:36; 1 Cr 6:78), atestiguada en la Estela de Moab, y (b) un descendiente de Aser (1 Cr 7:37). Su función como refugio para homicidas involuntarios la hace teológicamente relevante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87674, 'spa', 'Bosra (ciudad edomita)', 'Nombre propio de Bosra, la ciudad principal de Edom, que significa ''fortaleza.'' Aparece como patria de la realeza edomita (Gn 36:33 = 1 Cr 1:44) y como blanco profético de la ira divina: Isaías 34:6 retrata el sacrificio de YHWH allí, e Isaías 63:1 lo presenta viniendo de Bosra con vestiduras teñidas de carmesí. En Jeremías 48:24 el nombre podría designar un sitio moabita distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87682, 'spa', 'Vasija de barro', 'Frasco o vasija de barro cocido. La esposa de Ahías lleva ''un frasco de miel'' como obsequio (1 Reyes 14:3). Jeremías toma un ''frasco de alfarero'' y lo quiebra en el valle de Ben-hinom para simbolizar el juicio irrevocable de Dios sobre Jerusalén (Jeremías 19:1, 10). El sonido de gorgoteo al vaciar el recipiente le dio su nombre, y su fragilidad lo hizo apto para el simbolismo profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87683, 'spa', 'Levita portero', 'Un levita portero mencionado tres veces en las listas de Nehemías del personal del templo postexílico. La forma hebrea aparece siempre con la conjunción waw (''y-Bacbuquías''), indicando su inclusión en registros más amplios. Se encuentra exclusivamente en Nehemías, reflejando su papel específico en el servicio del templo restaurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87685, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que designa (a) a un líder danita encargado del reparto de Canaán (Nm 34:22), y (b) a un sacerdote de la línea aarónica a través de Eleazar y Finees, antepasado de Esdras (1 Cr 6:5, 51; Esd 7:4). Su uso dual en genealogías tribales y sacerdotales muestra la vigencia del nombre en distintos estratos israelitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87688, 'spa', 'Ser partido, ser hendido', 'Ser partido, ser hendido: formas pasivas o reflexivas que expresan el hecho de ser partido o quedar hendido — Nifal, Pual y Hitpael. La tierra «se abrió» bajo los rebeldes de Coré (Nm 16:31), el mar «fue dividido» en el Éxodo (Éx 14:21), y los odres viejos se describen como «rotos» (Jos 9:4, 13). Zacarías 14:4 profetiza que el Monte de los Olivos «se partirá en dos».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87689, 'spa', 'Partir, hender activamente', 'Partir, hender activamente: acción de partir o hender con fuerza directa — el sentido activo base del Qal y Piel. Abraham «partió» la leña para el holocausto (Gn 22:3), a Moisés se le ordenó «dividir» el mar con su vara (Éx 14:16), y Dios «hendió la roca» para dar agua (Jue 15:19; Sal 78:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87691, 'spa', 'Abrir brecha, irrumpir', 'Abrir brecha, irrumpir: abrir brecha en murallas o romper fortificaciones en contextos militares. Los valientes de David «irrumpieron» a través del campamento filisteo para sacar agua del pozo de Belén (2 S 23:16; 1 Cr 11:18). Cuando los muros de Jerusalén «fueron abiertos en brecha» en el 586 a.C., el Nifal pasivo describe la ciudad siendo abierta por la fuerza (2 R 25:4; Jer 52:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87692, 'spa', 'Empollar huevos', 'Empollar huevos: sentido biológico especializado confinado a las imágenes de Isaías. El búho «empollará» sus huevos en la desolación de Edom (Is 34:15), y los malvados «empollan huevos de víbora» (Is 59:5). Es una extensión metafórica del concepto de partir aplicada al nacimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87697, 'spa', 'Brotar, manar', 'Brotar, manar: brotar o manar con fuerza — agua de las rocas, manantiales de la tierra, o el alba que rompe. Las «fuentes del gran abismo se abrieron» en el Diluvio (Gn 7:11), manantiales «brotarán» en el desierto para los redimidos (Is 35:6), y la luz «despuntará como el alba» para el justo (Is 58:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87698, 'spa', 'Desgarrar, despedazar', 'Desgarrar, despedazar: desgarrar o abrir violentamente en el Piel intensivo, aplicado a cuerpos y seres vivos. La maldición de Eliseo trae osos que «despedazaron» a cuarenta y dos jóvenes (2 R 2:24). Las futuras atrocidades de Hazael incluyen «rasgar» a las mujeres embarazadas (2 R 8:12), y las piedras de granizo de Ezequiel «rompen» la pared encalada de los falsos profetas (Ez 13:11, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87739, 'spa', 'Valle amplio o llanura abierta formada entre montañas o colinas — paisaje ''hendi', 'Valle amplio o llanura abierta formada entre montañas o colinas — paisaje ''hendido'' por fuerzas geológicas. Se usa tanto para ubicaciones geográficas con nombre propio (בִּקְעַת יְרֵחוֹ, Dt 34:3; בִּקְעַת הַלְּבָנוֹן, Jos 11:17) como para descripción topográfica general (Dt 8:7; 11:11). El salmo de la creación (Sal 104:8) lo empareja con las montañas para describir el terreno que Dios modeló.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87752, 'spa', 'Ser vaciado (pasivo)', 'Estado pasivo de ser vaciado o quedar asolado, expresado mediante las formas del Nifal. Isaías 24:3 emplea la construcción enfática del infinitivo absoluto הִבּוֹק תִּבּוֹק (''será completamente vaciada''), en paralelo con ''totalmente saqueada,'' para describir una desolación total. Isaías 19:3 aplica la imagen figuradamente al espíritu de Egipto que es ''vaciado'': el coraje se escurre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87754, 'spa', 'Vaciar, devastar (activo)', 'Sentido activo de vaciar, devastar o asolar, empleado en las formas Qal y Poel. Isaías 24:1 declara a Dios como quien ''vacía la tierra,'' mientras Nahúm 2:2 describe a los guerreros enemigos como ''vaciadores'' que despojan todo. Jeremías 19:7 extiende la imagen figuradamente al consejo: Dios ''vaciará'' los planes de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87760, 'spa', 'Buscar, examinar, inspeccionar', 'Búsqueda activa, examen o inspección — el sentido central del Piel de investigación deliberada. En Ezequiel 34:11-12, Dios mismo «buscará» (אֲבַקֵּר) a su rebaño como un pastor busca ovejas dispersas, en paralelo con דָּרַשׁ. Levítico 13:36 y 27:33 lo usan para la inspección sacerdotal. Las traducciones al español «inspeccionaré/examinará» reflejan este sentido de indagación oficial y minuciosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87762, 'spa', 'Inquirir, consultar', 'Inquirir o buscar consejo, especialmente ante Dios — el impulso investigativo dirigido hacia la sabiduría divina. En 2 Reyes 16:15, Acaz reserva el altar de bronce «para consultar» (לְבַקֵּר), y el Salmo 27:4 lo empareja con חָזָה (''contemplar'') en el anhelo de admirar la hermosura de Dios. La traducción española «para consultar» destaca el registro consultivo de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87766, 'spa', 'Considerar, reflexionar', 'Reflexionar o considerar cuidadosamente — la extensión más interior de esta raíz. Proverbios 20:25 advierte contra atraparnos con palabras precipitadas, y luego «considerar» (לְבַקֵּר) lo que se ha prometido. La traducción «reconsiderar» capta adecuadamente esta ponderación cognitiva posterior al hecho, distinta de la búsqueda física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87767, 'spa', 'Investigar oficialmente', 'Buscar, indagar o investigar de manera oficial, referido a pesquisas archivísticas y administrativas realizadas por autoridad real. En Esdras 4:15 y 4:19 el Piel perfecto e imperfecto describen búsquedas en registros históricos; en 5:17 el Hitpael transmite un pasivo impersonal ''que se busque'' en el tesoro real. Las glosas españolas ''investigar'' y ''sea buscado'' reflejan ambas voces del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87768, 'spa', 'ganado vacuno, manada', 'Sustantivo colectivo para el ganado bovino — bueyes, vacas y becerros vistos como manada o individualmente. El término deriva de la raíz que significa ''arar'', reflejo de la centralidad agrícola del buey. Abarca listas patriarcales de riqueza (Gn 12:16), contextos sacrificiales (Nm 7:88) e imaginería profética (Is 11:7), y se traduce uniformemente en las lenguas meta: español ganado, francés bétail, alemán Herde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87813, 'spa', 'mañana', 'El período de luz diurna desde el alba hasta el mediodía, referido al punto del tiempo más que a una duración. Se usa literalmente para actividades matutinas — levantarse (Gn 22:3), ofrecer sacrificios matutinos (Ex 29:39) y montar la guardia de la mañana (Ex 14:24) — y figuradamente para la fidelidad divina que es ''nueva cada mañana'' (Lm 3:23). La fórmula de tarde a mañana estructura el cómputo temporal sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87836, 'spa', 'buscar, procurar', 'El sentido central del Piel: buscar activamente o procurar a alguien o algo. Cubre la gran mayoría de las ocurrencias, desde Saúl buscando las asnas de su padre (1 S 10:2) hasta enemigos que buscan la vida de David (1 S 23:10). El árabe طَلَبَ y بَحَثَ, el coreano 찾다/구하다 y el suajili kutafuta convergen en este sentido de búsqueda activa. La amplitud es notable: búsqueda física, indagación intelectual y anhelo espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87852, 'spa', 'requerir, demandar', 'Requerir, demandar o pedir cuentas, con la fuerza de la autoridad. Cuando Dios dice ''yo lo requeriré'' (Gn 9:5; 31:39; 2 S 4:11), el árabe يُطَالِبُ (''demandar legalmente'') y el suajili kudai (''reclamar/exigir'') captan el peso jurídico. No se trata de mera búsqueda sino de una exacción autoritativa, un llamamiento a rendir cuentas. El español demandar y el alemán fordern en las traducciones lo confirman.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87861, 'spa', 'pedir, suplicar', 'Pedir, rogar o suplicar, dirigido normalmente a un superior. En Est 4:8, Mardoqueo insta a Ester a suplicar ante el rey; en Esd 8:21 la comunidad busca a Dios mediante el ayuno. El árabe اِلْتَمَسَ (peticionar) y el suajili kuomba (pedir/orar) resaltan el tono suplicatorio. Este sentido pone en primer plano la asimetría relacional entre el peticionario y aquel a quien se dirige la petición, ya sea autoridad humana o divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87889, 'spa', 'ser buscado, investigado (Pual)', 'El Pual pasivo: ser buscado o investigado. En Jeremías 50:20 la iniquidad de Israel ''será buscada y no habrá ninguna'', y en Ester 2:23 el asunto ''fue investigado''. El árabe pasivo فُتِّشَ y el coreano 구해지다 reflejan la pasivización gramatical. Solo cuatro ocurrencias atestiguan esta forma, pero describen uniformemente un examen o pesquisa exhaustiva llevada a cabo sobre el sujeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87938, 'spa', 'examinar, evaluar', 'Una sola ocurrencia en Daniel 1:20, donde el rey ''buscó'' (examinó/evaluó) a los jóvenes y los halló superiores. Puede representar un matiz evaluativo especializado de la búsqueda, donde se indaga la calidad o competencia en lugar de la ubicación, tendiendo un puente entre los sentidos 1 y 2. El español les pidió y el alemán suchen preservan la ambigüedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87959, 'spa', 'Solicitud, petición, súplica', 'Petición formal dirigida a una persona con autoridad, especialmente un rey. Seis de las ocho apariciones se hallan en los diálogos de Ester con Asuero (Est 5:3, 6, 7, 8; 7:3; 9:12), donde la palabra porta el peso de una súplica de vida o muerte. En Esdras 7:6 describe la petición formal concedida por el rey persa. Los términos solicitud y súplica captan conjuntamente el sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87964, 'spa', 'Hijo (arameo)', 'Sustantivo masculino arameo que significa ''hijo,'' usado en cadenas constructas para patronímicos (Esd 5:1-2; 6:14), designaciones colectivas como ''hijos del cautiverio'' (Dn 5:13; 6:14) y la frase teológicamente significativa בַּר אֱנָשׁ (''como hijo de hombre,'' Dn 7:13). Es el equivalente arameo del hebreo בֵּן, con la terminación en nun característica del arameo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87969, 'spa', 'Hijo, descendiente', 'Hijo, descendiente: término arameo que funciona como sinónimo poético o elevado del hebreo בֵּן. En Prov 31:2 el triple vocativo (''hijo mío, hijo de mi vientre, hijo de mis votos'') adquiere calidez retórica por la forma aramea. En Sal 2:12 la palabra se sitúa en un contexto real-mesiánico: ''besad al Hijo, no sea que se enoje''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87970, 'spa', 'Puro, limpio', 'Puro, limpio o sincero, abarcando sentidos morales, rituales y físicos. Éticamente, describe la pureza de corazón requerida para el culto (Sal 24:4, בַר לֵבָב ''puro de corazón''; Sal 73:1, בָּרֵי לֵבָב). Se aplica a los mandamientos de Dios como perfectos y puros (Sal 19:9). En Cantares 6:9-10 describe a una doncella como ''pura'' o ''resplandeciente''. Job 11:4 lo usa como declaración de rectitud moral. En Proverbios 14:4 significa físicamente vacío o limpio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87976, 'spa', 'Grano almacenado', 'Grano como mercancía almacenada o transportada — cereal limpio y trillado, recogido en grandes cantidades. Este sentido domina la narrativa de José en Génesis: el faraón almacena grano durante los años de abundancia (Gn 41:35, 49), los hermanos viajan a Egipto a comprar grano (Gn 42:3), José llena sus costales de grano (Gn 42:25), y los asnos lo llevan de regreso a Jacob (Gn 45:23). Los Salmos 65:14 y 72:16 celebran el grano como señal de bendición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87977, 'spa', 'Grano profético y poético', 'Grano o trigo en contextos proféticos y poéticos, a menudo con un matiz cualitativo o metafórico. Jeremías 23:28 traza el célebre contraste: ''¿Qué tiene que ver la paja con el grano (בָּר)?'' — metáfora que distingue la profecía verdadera de la falsa. Joel 2:24 promete que las eras se llenarán de grano como señal de restauración. Amós 5:11 denuncia a quienes exigen tributos de grano a los pobres, y Amós 8:5–6 condena a los que falsean las medidas del grano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87982, 'spa', 'Campo silvestre', 'Sustantivo arameo para el campo abierto y no cultivado, dominio de los animales salvajes. Equivalente al hebreo sadeh, aparece en la frase construida khevat bar (''bestias del campo'') en Dan 2:38; 4:12, 15, 21, 23, 25, 32. El énfasis recae sobre el terreno agreste fuera de la habitación humana, especialmente prominente en la narrativa de la humillación de Nabucodonosor (Dan 4), donde el rey es expulsado al campo abierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87983, 'spa', 'Pureza moral', 'Limpieza o pureza moral de las manos como símbolo de conducta intachable ante Dios. Las cinco apariciones incluyen imaginería corporal: ''la limpieza de mis manos'' (2 Sam 22:21 = Sal 18:20; 2 Sam 22:25 = Sal 18:24) y ''la pureza de las palmas'' (Job 22:30). El español distingue ''limpieza'' de ''pureza'', reflejando el arco desde lo concreto hasta lo moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87985, 'spa', 'Qal', 'Qal: crear — crear por decreto divino, traer a la existencia lo que no existía. Se emplea exclusivamente con Dios como sujeto — 25 ocurrencias que abarcan la creación de los cielos y la tierra (Gn 1:1), las criaturas marinas y la humanidad (Gn 1:21, 27), y cosas nuevas por venir (Nm 16:30; Is 48:7). El verbo implica una originación divina sin esfuerzo, distinta de עָשָׂה (hacer).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87986, 'spa', 'Qal participio', 'Qal participio: Creador — participio usado como título divino sustantivado. Trece ocurrencias, predominantemente en Isaías (40:28; 42:5; 43:1, 15; 45:7, 18; 65:17), establecen בּוֹרֵא como epíteto permanente de Dios. El participio aparece frecuentemente en cadenas constructas: «Creador de los cielos», «Creador de los confines de la tierra».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87989, 'spa', 'Piel', 'Piel: talar, desmontar — cortar árboles o desmontar terreno boscoso para el asentamiento. Cinco ocurrencias, todas en contextos concretos: Josué dice a Efraín que «tale» el bosque en la región montañosa (Jos 17:15) y promete que «lo cortarán» (Jos 17:18). El cognado árabe bara (cortar, tallar una caña, dar forma a un palo) preserva esta dualidad léxica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (87990, 'spa', 'Nifal', 'Nifal: ser creado — pasivo: ser creado, llegar a existir por acto divino. Diez ocurrencias marcan el estado creado de las cosas — los cielos y la tierra «cuando fueron creados» (Gn 2:4); Adán y Eva «en el día en que fueron creados» (Gn 5:2); un pueblo futuro «que será creado» alabará al SEÑOR (Sal 102:18). La voz pasiva subraya que la existencia misma de las cosas es resultado de la acción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88024, 'spa', 'Piedras de granizo como fenómeno natural destructivo bajo control divino, usado ', 'Piedras de granizo como fenómeno natural destructivo bajo control divino, usado como instrumento de juicio. La narración de la plaga del Éxodo (Éx 9:18-34) ofrece la concentración más densa, con el granizo acompañado de truenos, lluvia y fuego. Josué 10:11 describe piedras de granizo letales que mataron a más amorreos que las espadas de Israel. Los Salmos celebran este arsenal divino (Sal 18:13; 78:47-48; 105:32; 148:8), y los profetas lo despliegan escatológicamente (Is 28:2, 17; Ez 38:22; Hag 2:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88031, 'spa', 'Manchado o moteado', 'De pelaje manchado o moteado, dicho de ovejas, cabras y caballos. En Gn 31:10, 12 forma una tríada con ''listados'' (עֲקֻדִּים) y ''salpicados'' (נְקֻדִּים), cada uno designando un patrón distinto de pelaje entre el ganado divinamente favorecido de Jacob. En Zac 6:3, 6 describe caballos que tiran de carros apocalípticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88032, 'spa', 'Comer, alimentarse', 'Comer, tomar alimento o hacer comer (alimentar). Usado en las conjugaciones Qal, Hifil y Piel en contextos de nutrición y sustento. En 2 Samuel 12:17, los siervos de David no logran persuadirlo de comer pan (בָּרָה) durante la enfermedad de su hijo. En la narrativa de Tamar (2 S 13:5-10), Amnón manipula la forma Hifil — «que ella me alimente» (תַּבְרֵנִי) — para atraer a su hermana. El Hifil en 2 Samuel 3:35 se refiere a hacer comer pan a David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88033, 'spa', 'Elegir, seleccionar', 'Elegir, seleccionar. Atestiguado únicamente en 1 Samuel 17:8, donde Goliat lanza su famoso desafío: בְּרוּ לָכֶם אִישׁ, «elegid para vosotros un hombre». Muchos eruditos consideran que se trata de una raíz distinta (בָּרָה II) y no de una extensión semántica de ''comer'', y el propio BDB señala la posibilidad de confusión escribal con בָּחַר (''elegir'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88038, 'spa', 'Nombre propio hebreo que significa ''bendito'' (de la raíz b-r-k), portado princip', 'Nombre propio hebreo que significa ''bendito'' (de la raíz b-r-k), portado principalmente por Baruc hijo de Nerías, el fiel escriba de Jeremías que escribió, leyó públicamente y reescribió el rollo profético tras su destrucción por Joacim (Jer 36:4-32), atestiguó la compra del campo en Anatot (Jer 32:12-16) y acompañó a Jeremías al exilio en Egipto (Jer 43:3, 6). También designa a Baruc hijo de Zabai, que reparó con notable celo una sección del muro de Jerusalén (Neh 3:20), y a un Baruc sacerdotal entre los selladores del pacto (Neh 10:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88040, 'spa', 'El ciprés (בְּרוֹשׁ), una conífera alta del Líbano y regiones circundantes cuya ', 'El ciprés (בְּרוֹשׁ), una conífera alta del Líbano y regiones circundantes cuya madera era muy estimada para la construcción sagrada y real. Los músicos de David tocaban instrumentos de madera de ciprés (2 S 6:5); Salomón encargó ciprés junto con cedro para los pisos y puertas del templo (1 R 5:8–10; 6:15, 34). Aparece también en contextos poéticos como símbolo de esplendor y permanencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88054, 'spa', 'Hierro (material y figurado combinados)', 'Hierro (material y figurado combinados): hierro en todas sus aplicaciones bíblicas: mineral en la tierra (Dt 8:9; Job 28:2), material trabajado para herramientas, armas y carros (Gn 4:22; Jos 17:16), y figura de fuerza y severidad opresiva — el «horno de hierro» de Egipto (Dt 4:20) y el «yugo de hierro» (Dt 28:48). Los cognados en arameo, acadio y árabe confirman un término metalúrgico semítico compartido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88065, 'spa', 'Nombre propio que designa principalmente a Barzilai el galaadita, el anciano ben', 'Nombre propio que designa principalmente a Barzilai el galaadita, el anciano benefactor que sustentó a David durante la rebelión de Absalón (2 S 17:27; 19:31-39; 1 R 2:7). También lo lleva una familia sacerdotal vinculada a sus descendientes (Esd 2:61; Neh 7:63). Todas las lenguas receptoras transliteran el nombre con variaciones fonológicas menores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88069, 'spa', 'Huir, escapar (Qal)', 'Huir, escapar (Qal): el sentido base del Qal: huir, escapar o fugarse del peligro, la persecución o la adversidad. Es con mucho el uso más frecuente (58 de 65 ocurrencias), que abarca las narraciones patriarcales (Gn 27:43; 31:20-22), los oráculos proféticos (Is 48:20) y la literatura sapiencial (Job 9:25; 27:22). Todas las traducciones principales convergen: huyó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88078, 'spa', 'Atravesar (infinitivo constructo)', 'Atravesar (infinitivo constructo): uso constructivo especializado donde la barra del tabernáculo «atraviesa» las tablas (Éx 36:33). El infinitivo constructo con lamed indica propósito o proceso — la barra se hace pasar por el medio de los bastidores. No es huida sino travesía lineal, una extensión espacial concreta de la semántica de movimiento de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88080, 'spa', 'Ahuyentar, poner en fuga (Hifil)', 'Ahuyentar, poner en fuga (Hifil): la forma causativa Hifil: hacer huir a alguien, ahuyentar o poner en fuga. En 1 Crónicas 8:13 los hombres de Gat son derrotados, y en Proverbios 19:26 un hijo vergonzoso «ahuyenta» a su madre. El español «hicieron huir» marca transparentemente la fuerza causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88087, 'spa', 'Atravesando (participio)', 'Atravesando (participio): forma participial que describe una barra «que pasa» o «que atraviesa» la estructura del tabernáculo (Éx 26:28). Estrechamente relacionada con el sentido 3 pero sintácticamente distinta como participio activo. El español «atravesando» confirma el carácter continuo y espacial de esta descripción arquitectónica — la barra central recorre toda la longitud del bastidor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88110, 'spa', 'Gordo, bien alimentado', 'Rollizo, carnoso y bien nutrido, describiendo animales o personas en estado de salud robusta o abundancia. Memorable sobre todo en el sueño del faraón con las siete vacas gordas (Gn 41:2–20), este adjetivo también caracteriza al ganado engordado destinado a las mesas reales (1 R 5:3) y a las ovejas prósperas en la alegoría del pastor de Ezequiel (Ez 34:3, 20). Aplicado a personas, describe a Eglón, el rey gordo de Moab (Jue 3:17), y la apariencia saludable de Daniel (Dn 1:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88121, 'spa', 'Alimento para enfermos', 'Comida especialmente preparada como sustento para el enfermo. Las tres apariciones se encuentran en 2 Samuel 13 durante el engaño de Amnón a Tamar. El artículo definido (הַ) sugiere un tipo de alimento específico y reconocible. El contexto transforma este acto de cuidado en instrumento de una trampa, dándole a la palabra una connotación ominosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88122, 'spa', 'Una barra de madera o metal usada como travesaño estructural en la construcción ', 'Una barra de madera o metal usada como travesaño estructural en la construcción del tabernáculo o como cerrojo que asegura las puertas de la ciudad. Las narrativas de la construcción del tabernáculo (Éx 26:26-29; 36:31-34; Nm 3:36; 4:31) y los pasajes de fortificación urbana (Dt 3:5; Jue 16:3; 1 R 4:13; Nah 3:13) constituyen el núcleo de uso. Las glosas multilingües convergen estrechamente: ''barras'', ''barres'', ''Riegel''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88145, 'spa', 'Un fugitivo o alguien que huye, procedente de la raíz homográfica barach que sig', 'Un fugitivo o alguien que huye, procedente de la raíz homográfica barach que significa ''huir'', sentido enteramente distinto del arquitectónico. Solo aparece en Isaías 15:5, refiriéndose a los fugitivos de Moab. Las traducciones confirman el cambio semántico: ''sus fugitivos'', señalando la diferencia respecto al sentido de barra o cerrojo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88147, 'spa', 'Huidizo o fugitivo', 'Describe movimiento de huida o fuga, ya sea de serpientes míticas o de refugiados humanos. Se presenta en dos contextos: (1) serpientes cósmico-mitológicas en Job 26:13 e Isaías 27:1, y (2) fugitivos humanos en Isaías 43:14. La dualidad semántica abarca desde lo monstruoso-celestial hasta lo humano-terrenal, unificada por la idea de desplazamiento veloz y evasivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88149, 'spa', 'Nombre personal que significa aproximadamente «en desgracia» o «en calamidad», l', 'Nombre personal que significa aproximadamente «en desgracia» o «en calamidad», llevado por varios personajes del Antiguo Testamento: (a) un hijo de Aser y ancestro del clan beriaíta (Gn 46:17; Nm 26:44-45; 1 Cr 7:30-31); (b) un hijo de Efraín nombrado así porque «la desgracia había caído sobre su casa» tras la muerte de sus hermanos a manos de los hombres de Gat (1 Cr 7:23); (c) un benjaminita de Ajalón cuyo clan expulsó a los habitantes de Gat (1 Cr 8:13, 16); (d) un levita gersonita, hijo de Simei (1 Cr 23:10-11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88156, 'spa', 'pacto, alianza, tratado', 'Acuerdo solemne y vinculante que establece obligaciones o promesas mutuas entre dos partes. Abarca los pactos de Dios con Noé, Abraham, Israel en el Sinaí y David, así como tratados políticos entre naciones (Gn 21:27; Jos 9:6) y convenios personales (Gn 31:44). La traducción uniforme como español pacto, francés alliance y alemán Bund subraya la gravedad del término como institución de compromiso sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88187, 'spa', 'Piel: bendecir', 'El sentido primario del Piel: otorgar activamente bendición o invocar el favor divino sobre alguien. El árabe بَرَكَة y el suajili bariki comparten la misma raíz semítica, subrayando la continuidad pansemítica. Desde Dios bendiciendo la creación (Gn 1:22, 28) hasta patriarcas bendiciendo a sus hijos (Gn 27:27) y sacerdotes bendiciendo al pueblo (Nm 6:23), este sentido impregna todos los registros de la vida bíblica — litúrgico, familiar y pactual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88188, 'spa', 'Qal pasivo: bendito', 'El participio Qal pasivo בָּרוּךְ: un estado de ser bendecido, usado predicativamente o como exclamación doxológica. El árabe مُبَارَك y el suajili mbarikiwa confirman la fuerza adjetival-estativa. ''Bendito sea Yahvé'' (Ex 18:10) y las fórmulas de bendición deuteronómicas (Dt 28:3-6) muestran a בָּרוּךְ funcionando como expresión característica de alabanza y gratitud en Israel — un estado declarado, no una acción ejecutada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88208, 'spa', 'Hitpael/Nifal: bendecirse', 'El sentido reflexivo-recíproco del Hitpael y Nifal: bendecirse a sí mismo, considerarse bendito o ser bendecido por asociación con otro. Es el sentido de la promesa abrahámica — ''en ti serán benditas todas las familias de la tierra'' (Gn 12:3; 22:18; 26:4). El árabe تَتَبَارَكُ (reflexivo Forma V) y el griego de la LXX ἐνευλογηθήσονται preservan el matiz mediador y autoimplicante que impulsa la promesa misionera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88224, 'spa', 'Pual: ser bendecido', 'El Pual (pasivo intensivo): ser bendecido, recibir bendición como sujeto. Distinto del participio Qal, el Pual transmite un evento de ser bendecido más que un estado estático. El árabe يُبَارَكُ (es bendecido, voz pasiva) y el coreano 복받다 (recibir bendición) lo distinguen de בָּרוּךְ. Dt 33:13 (la tierra de José ''es bendecida'') y Jue 5:24 (Jael ''la más bendita entre las mujeres'') ilustran esta forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88240, 'spa', 'Piel eufemístico: maldecir', 'El conocido Piel eufemístico: ''bendecir'' con el significado de maldecir o blasfemar contra Dios. Sustitución escribal (antífrasis) para evitar escribir la blasfemia abiertamente. Job 1:5, 11; 2:5, 9 y 1 R 21:10, 13 son los pasajes clave. El suajili laani (maldecir) y el árabe جَدَّفَ (blasfemar) traducen el significado intencional. El contexto y el tronco Piel son las únicas pistas del lector — un fenómeno único en el léxico hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88264, 'spa', 'Qal: arrodillarse', 'La raíz física-gestual original: arrodillarse o postrarse, atestiguada en el tronco Qal. El árabe بَرَكَ (un camello se arrodilló) preserva el significado corporal. Solo dos casos claros permanecen — Salomón arrodillándose (2 Cr 6:13) y la invitación del salmista ''arrodillémonos ante Yahvé'' (Sal 95:6) — pero anclan todo el vocabulario de la bendición en una postura concreta de adoración y sumisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88292, 'spa', 'Hifil: hacer arrodillar', 'Uso causativo del Hifil: hacer arrodillar, poner de rodillas. Gn 24:11 registra al siervo de Abraham haciendo arrodillar a los camellos junto al pozo. El árabe أَبْرَكَ (lo hizo arrodillarse) tiene un paralelo preciso con esta forma causativa. Esta única ocurrencia preserva la extensión transitiva-causativa del sentido físico de la raíz, tendiendo un puente entre el acto corporal de arrodillarse y el acto teológico de bendecir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88326, 'spa', 'Arrodillarse y bendecir', 'Arrodillarse en oración o bendecir y alabar a Dios, abarcando tanto la postura física de adoración como el acto verbal de doxología. Dn 6:10 emplea el participio Peal para arrodillarse, mientras Dn 2:19 y 4:34 usan el Pael para bendecir a Dios tras recibir revelación. El participio pasivo en Dn 3:28 (''bendito sea el Dios de Sadrac...'') muestra un uso doxológico litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88327, 'spa', 'La articulación anatómica de la pierna, usada literal e idiomáticamente', 'La articulación anatómica de la pierna, usada literal e idiomáticamente. Físicamente, las rodillas flaquean por enfermedad (Dt 28:35), tiemblan de debilidad (Dn 10:10) o se sumergen en agua creciente (Ez 47:4). Ritualmente, arrodillarse expresa adoración (Is 45:23; 1 R 19:18), oración (Esd 9:5) o súplica (2 R 1:13). La expresión de nacimiento ''dar a luz sobre las rodillas'' (Gn 30:3; 50:23) señala adopción legal. Las 26 apariciones apuntan todas a un mismo referente físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88346, 'spa', 'Bendición, favor divino', 'Bendición, favor divino: el acto o contenido de pronunciar bien sobre alguien, ya sea de Dios a los humanos o entre personas, incluyendo las bendiciones patriarcales, las promesas de prosperidad del pacto y las bendiciones litúrgicas. Este sentido abrumadoramente dominante (68 ocurrencias) va desde la promesa fundacional de Dios a Abraham — «te haré una bendición» (Gn 12:2) — hasta las bendiciones patriarcales de Isaac (Gn 27), Jacob (Gn 49:28) y Moisés (Dt 33:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88370, 'spa', 'Don, oferta de paz', 'Don, oferta de paz: un regalo concreto o una ofrenda de paz — una muestra tangible de buena voluntad extendida como gesto diplomático, donde el concepto abstracto de «bendición» se materializa en algo que se da o intercambia. Solo una ocurrencia clara en este corpus: la burla del Rabsaces asirio a Jerusalén, «haced paz conmigo y salid a mí» (Is 36:16), donde בְּרָכָה funciona como una oferta de términos — rendición a cambio de la promesa de bienestar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88372, 'spa', 'Nombre propio: bendición', 'Nombre propio que significa ''bendición'', referido tanto a una persona como a un lugar. El guerrero Beraca aparece en 1 Crónicas 12:3 entre los valientes de David. El Valle de Beraca (2 Cr 20:26, dos veces) es donde Judá se congregó para bendecir a Dios tras la victoria. La conjunción ''y-Beraca'' en las listas indica su integración en registros más amplios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88373, 'spa', 'Cuerpo de agua estancada, natural o artificial, utilizado para recolección, alma', 'Cuerpo de agua estancada, natural o artificial, utilizado para recolección, almacenamiento o riego. Aparece como punto de referencia cívico en las narrativas: el estanque de Gabaón (2 S 2:13), el estanque de Samaria (1 R 22:38), el estanque superior (Is 7:3; 36:2) y el proyecto de embalse de Ezequías (2 R 20:20). Salomón construyó estanques para irrigar sus jardines (Ec 2:6), y Nahúm lo usa como símil de la huida de Nínive (Nah 2:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88380, 'spa', 'Nombre personal teofórico que significa «el SEÑOR ha bendecido», llevado por múl', 'Nombre personal teofórico que significa «el SEÑOR ha bendecido», llevado por múltiples figuras del Antiguo Testamento. El más notable es el padre (o abuelo) del profeta Zacarías (Zac 1:1, 7). También: (a) un descendiente postexílico de David (1 Cr 3:20); (b) el padre de Asaf, músico levita (1 Cr 6:39; 15:17); (c) un portero del arca durante su traslado a Jerusalén (1 Cr 15:23); (d) un efrainita que intercedió a favor de los cautivos de Judá (2 Cr 28:12); (e) el padre de Mesulam, que reparó el muro de Jerusalén (Neh 3:4, 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88383, 'spa', 'Conjunción adversativa', 'Conjunción adversativa que significa ''pero, sin embargo, no obstante'', usada para introducir una cláusula que contrasta o anula lo que la precede. En Dn 2:28 pivota dramáticamente de la insuficiencia humana a la revelación divina (''pero hay un Dios en el cielo''). En Dn 4:15 y 4:23 limita un decreto de destrucción (''pero dejad el tocón de sus raíces'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88387, 'spa', 'Un destello de relámpago, ya sea descarga atmosférica literal o figurado del pod', 'Un destello de relámpago, ya sea descarga atmosférica literal o figurado del poder y la brillantez divinos. Predominantemente en plural para los destellos de relámpago en la teofanía del Sinaí (Éx 19:16) y en los Salmos (77:18; 97:4; 135:7). En singular en Sal 144:6 como arma que Dios lanza. Figuradamente, describe el filo reluciente de la espada de Dios (Dt 32:41) y el destello veloz del metal de los carros (Nah 2:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88397, 'spa', 'Barak', 'El nombre personal Barak (que significa ''destello de relámpago''), que identifica al hijo de Abinoam de Cedes de Neftalí, quien sirvió como comandante militar de Israel en la batalla contra las fuerzas cananeas de Sísara. Todas las apariciones se encuentran en Jueces 4:6–22 (el relato en prosa) y Jueces 5:1, 12, 15 (el cántico de victoria de Débora y Barak). El nombre es cognado del púnico ''Barcas'', célebre apellido del clan de Amílcar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88404, 'spa', 'Escogido, selecto, de la más fina calidad — el participio pasivo Qal funcionando', 'Escogido, selecto, de la más fina calidad — el participio pasivo Qal funcionando como adjetivo. En 1 Cr 7:40 y 9:22, los guerreros son descritos como hombres ''escogidos''. Nehemías 5:18 enumera ovejas ''selectas'' preparadas diariamente. Job 33:3 habla de palabras ''puras'' — cuidadosamente seleccionadas y claras. La imagen subyacente de cribar conecta esta acepción con la purificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88405, 'spa', 'Ser puro, purificarse o purgar — usado en las conjugaciones reflexivas y causati', 'Ser puro, purificarse o purgar — usado en las conjugaciones reflexivas y causativas para la limpieza moral y ritual. En Sal 18:26 y 2 S 22:27, Dios se muestra puro con el de corazón puro. Ezequiel 20:38 usa el verbo para el acto soberano de Dios de purgar a los rebeldes de entre su pueblo. Daniel 12:10 extiende esto a la prueba escatológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88412, 'spa', 'Afilar o pulir armas — la conjugación Hifil en su aplicación más concreta y físi', 'Afilar o pulir armas — la conjugación Hifil en su aplicación más concreta y física. En Jer 51:11, el Señor ordena: ''¡Afilen las flechas!'' cuando se acerca el juicio sobre Babilonia. Esta única aparición preserva la conexión de la palabra con la artesanía material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88422, 'spa', 'Arroyo en Filistea', 'Un cauce estacional (wadi) en territorio filisteo, que aparece siempre con artículo definido como ''el Besor'' (נַחַל הַבְּשׂוֹר). Las tres apariciones se encuentran en 1 Samuel 30, marcando el lugar donde David dividió sus fuerzas durante la persecución de los amalecitas. El sitio adquirió importancia jurídica como lugar del decreto sobre el reparto equitativo del botín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88423, 'spa', 'Noticia, nueva', 'Noticia o nueva, frecuentemente con connotación positiva: el informe traído por un corredor desde el campo de batalla o una escena dramática. Cinco ocurrencias se agrupan en torno a la narrativa de Absalón (2 Sam 18:20, 22, 25, 27) y el descubrimiento de los leprosos (2 Re 7:9). Las evidencias interlingüísticas reflejan consistentemente la expectativa positiva asociada a esta palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88425, 'spa', 'Recompensa al mensajero', 'La recompensa o pago entregado al portador de buenas noticias, una extensión metonímica desde la noticia misma hacia la compensación esperada por su mensajero. En 2 Samuel 4:10, David recuerda irónicamente cómo trató a un mensajero previo que esperaba una recompensa (besorah) por su informe. El español «recompensa» capta este sentido concreto y transaccional, distinto del mensaje en sí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88426, 'spa', 'El acto culinario de cocinar o hervir alimentos calentándolos en líquido, usado ', 'El acto culinario de cocinar o hervir alimentos calentándolos en líquido, usado predominantemente en el tronco Piel para la cocción activa y en el Pual para la pasiva. Abarca la preparación sacrificial (Éx 29:31), la elaboración de comidas ordinarias (2 S 13:8) e incluso la desgarradora imagen de madres cociendo a sus propios hijos durante un asedio (Lm 4:10). La prohibición de cocer un cabrito en la leche de su madre (Éx 23:19) es emblemática de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88430, 'spa', 'El proceso natural por el que un fruto o grano alcanza su plena madurez, extensi', 'El proceso natural por el que un fruto o grano alcanza su plena madurez, extensión del dominio del calor culinario al calor del sol que lleva los productos a la sazón. Joel 3:13 convoca a la hoz porque la cosecha está madura (bashal), y Génesis 40:10 describe uvas madurando en la vid. Este sentido botánico se distingue claramente del significado culinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88454, 'spa', 'Especia, perfume o resina de bálsamo aromático utilizado en contextos sagrados y', 'Especia, perfume o resina de bálsamo aromático utilizado en contextos sagrados y reales. En el ámbito cultual, es un ingrediente obligatorio para el aceite de la santa unción y el incienso (Éx 25:6; 30:23; 35:8, 28). En los relatos reales, las especias funcionan como tesoros costosos y regalos diplomáticos (1 R 10:2, 10; 2 R 20:13; 2 Cr 9:1, 9). En el Cantar de los Cantares, la forma plural se convierte en metáfora del atractivo del amado (Cnt 4:10, 14, 16; 5:1, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88473, 'spa', 'Basemat (nombre propio)', 'El nombre propio Basemat (בָּשְׂמַת, ''fragante''), que designa a: (1) una mujer hitita, hija de Elón, esposa de Esaú (Gn 26:34); (2) una hija de Ismael y esposa de Esaú (Gn 36:3, 4, 10, 13, 17 — el Pentateuco Samaritano lee Mahalat en todo Génesis 36, reflejando una tradición textual que armonizó los nombres); y (3) una hija de Salomón casada con Ahimaaz (1 R 4:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88476, 'spa', 'Basán (territorio)', 'Basán (territorio): el nombre propio territorial de la región de Basán al este del Jordán, que abarca los actuales Altos del Golán y la meseta del Haurán — originalmente el reino de Og (Nm 21:33; Dt 3:1-3), y luego símbolo de fertilidad excepcional. Sus encinas, toros y vacas se convirtieron en imágenes proverbiales de fuerza y abundancia (Sal 22:12; Am 4:1; Is 2:13). Todas las lenguas modernas transliteran en lugar de traducir, confirmando su estatus como topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88487, 'spa', 'Llevar o proclamar buenas nuevas, especialmente noticias de victoria militar o l', 'Llevar o proclamar buenas nuevas, especialmente noticias de victoria militar o liberación divina (Piel). El mensajero del campo de batalla que corre a anunciar el resultado de la guerra es el uso paradigmático (2 S 18:19-20; 1 S 31:9). Isaías transforma esto en proclamación escatológica: el heraldo anuncia el reinado de Dios y la salvación a Sion (Is 40:9; 41:27; 52:7; 61:1). La forma participial מְבַשֵּׂר se convierte en la raíz del concepto neotestamentario de «evangelio».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88507, 'spa', 'cuerpo, ser físico', 'El cuerpo vivo como totalidad, el ser corpóreo como opuesto al espíritu, el alma o la vida interior — el sentido abrumadoramente dominante con 207 ocurrencias. ''Toda carne'' (כָּל בָּשָׂר) es un modismo estándar para todos los seres vivientes o toda la humanidad (Gn 6:12-13, 17). El suajili mwili, el hindi शरीर y el coreano 육체 seleccionan uniformemente vocabulario de ''cuerpo/ser físico''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88509, 'spa', 'carne, sustancia comestible', 'Carne o sustancia comestible — tejido animal como alimento, material sacrificial o sustancia física, con 49 ocurrencias. Las instrucciones de Pascua especifican comer la בָּשָׂר asada (Ex 12:8); los israelitas anhelan בָּשָׂר en el desierto (Nm 11:4-13); los sacerdotes consumen la בָּשָׂר de la ofrenda de paz (Ex 29:31-32). El coreano 고기 y el suajili nyama seleccionan consistentemente vocabulario de ''carne/alimento''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88512, 'spa', 'piel, superficie corporal', 'La piel exterior o superficie corporal, sentido especializado que aparece 14 veces casi exclusivamente en la legislación sacerdotal y médica sobre enfermedades cutáneas y flujos corporales (Lv 13-15; 2 R 5:10-14). Cuando el sacerdote inspecciona una ''hinchazón en la carne'', el significado es claramente dermatológico, no del cuerpo entero. El suajili ngozi (''piel''), el árabe بَشَرَة (''epidermis'') y la propia nota de cognados del BDB lo confirman.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88568, 'spa', 'Carne, seres vivientes', 'Sustantivo arameo para carne, empleado en tres contextos en Daniel: (1) carne como alimento de bestias (Dn 7:5), (2) carne como humanidad o mortales, en contraste con la divinidad (Dn 2:11), y (3) toda criatura viviente, es decir «toda carne» (Dn 4:12). La raíz comparte cognados con el siríaco y el arameo targúmico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88569, 'spa', 'Vergüenza, deshonra o humillación como condición abstracta', 'Vergüenza, deshonra o humillación como condición abstracta. El sentido dominante en 30 apariciones describe el estado de ser avergonzado ante Dios, los enemigos o la sociedad. Se encuentra en construcciones como boshet panim (''vergüenza del rostro'', Dn 9:7-8; Esd 9:7), labash boshet (''vestirse de vergüenza'', Job 8:22; Sal 35:26) y como fruto amargo de la idolatría (Jer 3:24-25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88587, 'spa', 'Un elemento de nombre propio (Bosheth) sustituido por escribas posteriores en lu', 'Un elemento de nombre propio (Bosheth) sustituido por escribas posteriores en lugar del nombre divino Baal en nombres personales israelitas, reflejando aversión teológica hacia la deidad cananea. Esta aparición única (2 S 21:7) conserva el nombre Mefi-boset, donde -boset reemplaza al original -baal. Todas las traducciones simplemente transliteran como bosheth/boshet, señalando el reconocimiento de la función de nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88590, 'spa', 'hija, descendiente femenina', 'Hija en relación con sus padres; por extensión nieta, descendiente femenina, mujer joven o mujer perteneciente a un pueblo o lugar (''hija de Sion''). Se traduce como hija (esp.), fille (fr.), Tochter (al.) a lo largo de 545 ocurrencias. Incluye el trato vocativo a una mujer joven (Rt 2:8) y marcadores de identidad colectiva como ''hijas de Israel'' (2 S 1:24; 1 Cr 3:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88599, 'spa', 'aldea dependiente, poblado', 'Aldea dependiente o asentamiento satélite que rodea a una ciudad fortificada mayor, donde las ''hijas'' son poblados sin muralla vinculados económica y defensivamente a la ciudad madre. Los traductores al español pasan de hija a aldeas en estos contextos, confirmando el salto metafórico del parentesco a la geografía. Concentrado en narrativas de conquista y asentamiento (Nm 21:25, 32; Jos 15:45; Jos 17:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88703, 'spa', 'Bato (medida de líquido)', 'Unidad estándar hebrea de volumen líquido equivalente a unos 22 litros, empleada para medir vino, aceite y agua en contextos comerciales, litúrgicos y agrícolas. Se define como una décima parte del homer y equivale al efa seco (Ez 45:11, 14). El mar de bronce de Salomón contenía 2.000 batos (1 R 7:26; 2 Cr 4:5) y cada una de las diez pilas contenía 40 batos (1 R 7:38). En Isaías 5:10, la escasa producción de un solo bato ilustra el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88711, 'spa', 'Betuel (nombre propio)', 'Betuel — nombre propio (posiblemente ''hombre de Dios'') del hijo de Nacor y Milca, sobrino de Abraham, y padre de Rebeca y Labán. Aparece principalmente en la narrativa del compromiso matrimonial de Génesis 24, donde el siervo de Abraham viaja a la ciudad de Nacor en Aram-Naharaim para encontrar esposa para Isaac (Gn 24:15, 24, 47, 50). La fuente sacerdotal lo identifica como ''Betuel el arameo de Padán-Aram'' (Gn 25:20; 28:2, 5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88716, 'spa', 'Virgen, mujer joven (sentido combinado)', 'Virgen, mujer joven (sentido combinado): mujer joven definida por la virginidad, que abarca tanto el sentido literal de doncella soltera en la casa paterna (Gn 24:16; Éx 22:16-17; Lv 21:3, 14; Dt 22:19, 23, 28) como la personificación figurada de ciudades y naciones — para expresar vulnerabilidad, pureza o el dolor de la devastación (Is 37:22; Am 5:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88733, 'spa', 'El estado de virginidad o la evidencia física (señales) que demuestra la pureza ', 'El estado de virginidad o la evidencia física (señales) que demuestra la pureza sexual de una novia antes del matrimonio. Central en el procedimiento legal de Deuteronomio 22:14-20, donde las «señales de virginidad» debían exhibirse ante los ancianos de la ciudad para vindicar a una esposa acusada. También se emplea para el requisito matrimonial del sumo sacerdote (Lv 21:13) y el lamento de la hija de Jefté por su virginidad (Jue 11:37-38). Ezequiel 23:3, 8 lo usa figuradamente para la infidelidad de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88743, 'spa', 'Partes del sacrificio', 'Piezas o mitades de animales divididos en ritos de alianza. Génesis 15:10 usa el singular («su mitad») para el rito de Abraham, mientras que Jeremías 34:18-19 emplea formas plurales («las partes del becerro») para el pacto violado. La raíz hebrea apunta a la acción de cortar o hender, y el término subraya la solemnidad del compromiso pactado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88747, 'spa', 'Betsabé (nombre propio)', 'Betsabé (nombre propio). Nombre propio de una mujer de Jerusalén, esposa de Urías el hitita y después esposa del rey David, madre de Salomón. Las once ocurrencias se concentran en 2 Samuel 11-12 y 1 Reyes 1-2, abarcando el arco narrativo desde el adulterio de David hasta la entronización de Salomón. El nombre compuesto bat-sheva puede significar ''hija de un juramento'' o ''hija de abundancia''. Aparece en la genealogía de Jesús en Mateo (Mt 1:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88752, 'spa', 'Levantarse, crecer, ensalzarse', 'Levantarse, crecer o ser ensalzado, empleado en contextos tanto literales como figurados. De aguas que suben: el río del templo de Ezequiel que había crecido (גָּאוּ) hasta ser imposible de vadear (Ez 47:5). De plantas que crecen: Job 8:11 pregunta si los juncos pueden crecer (יִגְאֶה) sin agua. Del triunfo divino: el emblemático Cántico del Mar (Éx 15:1, 21) con su acusativo cognado intensificador גָּאֹה גָּאָה, ''ha triunfado gloriosamente''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88757, 'spa', 'Soberbio, arrogante', 'Describe a una persona soberbia, arrogante o altiva, típicamente en oposición a Dios o en opresión de otros. En Job 40:11-12, YHWH ordena que todo soberbio sea abatido. El Salmo 94:2 clama retribución contra los arrogantes, y Proverbios 15:25 declara que el SEÑOR derribará la casa del soberbio. El español ''soberbio'' y el francés orgueilleux captan con precisión este sentido negativo y moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88764, 'spa', 'Orgullo pecaminoso, insolencia o arrogancia autoexaltante que provoca el juicio ', 'Orgullo pecaminoso, insolencia o arrogancia autoexaltante que provoca el juicio divino. Los Salmos lo condenan repetidamente: el impío persigue con ardor al pobre ''con soberbia'' (Sal 10:2), el orgullo es collar que adorna al violento (Sal 73:6). Isaías 9:8 y 13:11 apuntan al orgullo de Efraín y la arrogancia de los despiadados. Proverbios 29:23 distingue nítidamente entre el orgullo que humilla y la humildad que honra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88768, 'spa', 'Majestad, excelencia o grandeza digna — cualidad positiva atribuida a Dios o con', 'Majestad, excelencia o grandeza digna — cualidad positiva atribuida a Dios o conferida por Dios. Deuteronomio 33:26 celebra al Dios de Jesurún que ''cabalga por los cielos en su majestad'', y 33:29 declara bienaventurado a Israel por la excelencia divina. El Salmo 68:34 atribuye esta grandeza a Dios sobre Israel. Isaías 13:3 la aplica a los guerreros convocados por Dios para ejecutar su juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88781, 'spa', 'Orgullo, arrogancia (negativo)', 'Orgullo, arrogancia (negativo): el sentido negativo dominante: orgullo pecaminoso, arrogancia o altivez — la autoexaltación de personas o naciones que se elevan contra Dios. Es el uso característico de los profetas: «quebrantaré la soberbia de vuestro poder» (Lv 26:19), «castigaré al mundo por su maldad, y a los arrogantes por su soberbia» (Is 13:11). Proverbios 8:13 lo incluye entre las cosas que el SEÑOR aborrece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88782, 'spa', 'Majestad, excelencia (divina)', 'Majestad, excelencia (divina): el sentido teológico positivo: la grandeza majestuosa, la excelencia y el esplendor de Dios mismo. En el Cántico del Mar, Moisés canta «en la grandeza de tu majestad derribas a tus adversarios» (Éx 15:7). Job 37:4 describe la voz atronadora de Dios como inseparable de su גָּאוֹן. En Job 40:10 Dios desafía a Job a «vestirse de majestad y dignidad».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88784, 'spa', 'Gloria, honra (de pueblos o tierras)', 'Gloria, honra (de pueblos o tierras): un sentido positivo intermedio: gloria, esplendor u orgullo legítimo asociado a un pueblo, una tierra o una herencia — no arrogancia pecaminosa sino honor merecido. El Salmo 47:4 celebra que Dios «escogió nuestra heredad, el orgullo de Jacob a quien amó». Isaías 4:2 vislumbra al «renuevo del SEÑOR» como «la hermosura y la gloria» de los sobrevivientes de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88786, 'spa', 'Espesura (del Jordán)', 'Espesura (del Jordán): uso concreto geográfico distintivo que se encuentra en Jeremías 49:19 y 50:44, donde la frase «la espesura del Jordán» (גְּאוֹן הַיַּרְדֵּן) describe la densa y exuberante vegetación a lo largo del río Jordán — su «desbordamiento» o «frondosidad» expresada como maleza exuberante. El español «espesura de» conserva la imagen concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88810, 'spa', 'Soberbia, arrogancia', 'Soberbia, arrogancia u orgullo humano — el alzarse de la autoexaltación contra Dios o contra otros. Isaías condena la ''corona de soberbia'' (ateret ge''ut) de los borrachos de Efraín (Is 28:1, 3), y el salmista lamenta a quienes ''hablan con arrogancia'' (Sal 17:10). El español ''soberbia/arrogancia'' y el alemán Stolz marcan consistentemente este sentido negativo y moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88812, 'spa', 'Elevación física', 'Elevación o ascenso físico, específicamente del humo. En Isaías 9:18, la maldad arde como fuego y sube como ''columna de humo'' (ge''ut ashan). El español ''columnas de'' y el inglés ''rising of'' captan la imagen concreta y visual. Esta única ocurrencia física preserva el significado espacial originario de la raíz — movimiento ascendente — antes de su extensión metafórica a la soberbia y la majestad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (88813, 'spa', 'Majestad, exaltación', 'Majestad, exaltación o grandeza divina — el alzarse propio y glorioso que pertenece a Dios. YHWH está ''vestido de majestad'' (Sal 93:1); sus obras la manifiestan (Is 12:5); pero los impíos no perciben su majestad (Is 26:10). El español ''majestad/grandeza'' y el alemán Majestät distinguen este sentido teológico positivo de la soberbia humana.');